"use client";
import { useState } from "react"; import { ChevronDown } from "lucide-react";
export function Section({eyebrow,title,children,className=""}:{eyebrow?:string;title:string;children:React.ReactNode;className?:string}){return <section className={`container py-14 md:py-20 ${className}`}><div className="max-w-3xl">{eyebrow&&<p className="mb-3 text-xs font-bold uppercase tracking-[.18em] text-teal-700">{eyebrow}</p>}<h2 className="text-3xl font-extrabold tracking-tight md:text-4xl">{title}</h2></div>{children}</section>}
export function FAQ({items}:{items:{q:string;a:string}[]}){const [active,setActive]=useState<number|null>(null);return <div className="mt-8 divide-y rounded-2xl border border-slate-200 bg-white dark:border-slate-700 dark:bg-[#10232d]">{items.map((x,i)=><div key={x.q}><button className="flex w-full items-center justify-between gap-5 p-5 text-left font-bold" aria-expanded={active===i} onClick={()=>setActive(active===i?null:i)}>{x.q}<ChevronDown className={active===i?"rotate-180 transition":"transition"}/></button>{active===i&&<p className="px-5 pb-5 leading-7 text-slate-600 dark:text-slate-300">{x.a}</p>}</div>)}</div>}
export function Definition({children}:{children:React.ReactNode}){return <div className="mt-6 rounded-2xl border-l-4 border-teal-600 bg-mint p-5 text-slate-700 dark:bg-teal-950 dark:text-slate-100">{children}</div>}
